arguments.command:
# No .rela.plt section - so the PLT is resolved via .rela.dyn. 
# Let's find JUMP_SLOT entries in .rela.dyn
BINFILE="/tmp/symbols/libmonosgen-2.0.so.dbg"
aarch64-linux-gnu-readelf -r "$BINFILE" 2>/dev/null | grep "JUMP_SLO" | head -5
echo "==="
# Actually these might not be PLT entries at all. Let me check what section 0x2f4b20 falls in more precisely
aarch64-linux-gnu-readelf -S "$BINFILE" 2>/dev/null | awk '
/\[/ {
  if (NF >= 7) {
    name = $2
    addr = strtonum("0x" $4)
    off = strtonum("0x" $5)
    size = strtonum("0x" $6)
    if (addr <= strtonum("0x2f4b20") && addr + size > strtonum("0x2f4b20")) {
      printf "0x2f4b20 is in section %s (addr=0x%x size=0x%x)\n", name, addr, size
    }
  }
}'

